<template>
  <view class="sm-issue-editor">
    <text class="sm-h3">{{ title }}</text><text class="sm-help">紧急问题可先登记并处置、上报，无须等待整张日表填写完成。保存本记录不代表实际上报或已销号。</text>
    <view class="sm-field"><text class="sm-field-label">隐患关联方式</text><view class="sm-options"><view v-for="option in modes" :key="option.value" :class="['sm-option',{'sm-option--active':mode===option.value}]" @click="mode=option.value">{{ option.label }}</view></view></view>
    <view v-if="mode==='existing'" class="sm-field"><text class="sm-field-label">关联本厂站未关闭隐患</text><picker v-if="openHazards.length" :range="openHazards" range-key="optionLabel" @change="form.existing_hazard_id=openHazards[Number($event.detail.value)]._id"><view class="sm-picker">{{ selectedHazardLabel || '从待办隐患选择 ▾' }}</view></picker><input v-model="form.existing_hazard_id" class="sm-input" placeholder="或输入原隐患 ID" /><text class="sm-help">会增加本次观察记录，不重复创建隐患。</text></view>
    <view v-if="mode==='recurrence'" class="sm-field"><text class="sm-field-label">选择已复查销号的历史隐患</text><view class="sm-row"><input v-model="closedQuery" class="sm-input sm-closed-query" placeholder="按隐患编号、描述搜索" @confirm="searchClosed(false)" /><button class="sm-btn sm-btn--secondary sm-btn--small" :disabled="closedLoading" @click="searchClosed(false)">{{ closedLoading?'查询中…':'查询已关闭隐患' }}</button></view><text v-if="closedError" class="sm-alert sm-alert--error">{{ closedError }}</text><view v-for="hazard in closedHazards" :key="hazard._id" :class="['sm-closed-result',{'sm-closed-result--selected':form.recurrence_of===hazard._id}]" @click="selectRecurrence(hazard)"><text class="sm-h3">{{ hazard.hazard_no }}</text><text class="sm-text">{{ hazard.issue_note }}</text><text class="sm-help">原责任人：{{ hazard.responsible_name }} · 销号时间：{{ formatDateTime(hazard.verified_at) }} {{ form.recurrence_of===hazard._id?' · 已明确选择':'' }}</text></view><button v-if="closedHasMore" class="sm-btn sm-btn--secondary sm-btn--small" :disabled="closedLoading" @click="searchClosed(true)">查看更多已关闭隐患</button><text v-if="closedSearched && !closedHazards.length && !closedError" class="sm-help">没有符合条件的已关闭隐患，可调整关键词重试。</text><text v-if="selectedRecurrence" class="sm-alert sm-alert--info">复发来源：{{ selectedRecurrence.hazard_no }} · {{ selectedRecurrence.issue_note }}。此次将创建新隐患，保留与历史事件的关联。</text><text v-else class="sm-help">请查询后明确选中一条原隐患；系统不会按名称相似度自动关联。</text></view>
    <label class="sm-field"><text class="sm-field-label">实际发现时间（北京时间）</text><input v-model="discovered" class="sm-input" placeholder="YYYY-MM-DD HH:mm" /></label>
    <label class="sm-field"><text class="sm-field-label">本次问题描述 *</text><textarea v-model="form.issue_note" class="sm-textarea" maxlength="2000" placeholder="具体部位、异常现象及本次变化" /></label>
    <view class="sm-grid"><view class="sm-field"><text class="sm-field-label">隐患等级 *</text><view class="sm-options"><view v-for="level in levels" :key="level.value" :class="['sm-option',{'sm-option--active':form.hazard_level===level.value}]" @click="form.hazard_level=level.value">{{ level.label }}</view></view></view><label class="sm-field"><text class="sm-field-label">整改责任人 *</text><input v-model="form.responsible_name" class="sm-input" maxlength="50" placeholder="实际责任人姓名" /></label></view>
    <label class="sm-field"><text class="sm-field-label">整改要求 / 计划措施 *</text><textarea v-model="form.planned_measure" class="sm-textarea" maxlength="2000" /></label>
    <view class="sm-field"><text class="sm-field-label">计划完成日期 *</text><picker mode="date" :value="form.planned_complete_date" @change="form.planned_complete_date=$event.detail.value"><view class="sm-picker">{{ form.planned_complete_date || '选择日期' }}</view></picker></view>
    <label class="sm-field"><text class="sm-field-label">临时管控措施</text><textarea v-model="form.temporary_controls" class="sm-textarea" maxlength="2000" /></label>
    <SafetyEvidenceEditor v-model="form.evidence" @busy="evidenceUploading=$event" />
    <view class="sm-expand sm-link" @click="showReport=!showReport">{{ showReport ? '收起' : '填写' }}实际上报事实 {{ showReport ? '−' : '+' }}</view>
    <view v-if="showReport"><view class="sm-grid"><label class="sm-field"><text class="sm-field-label">上报时间（北京时间）</text><input v-model="reported" class="sm-input" placeholder="YYYY-MM-DD HH:mm" /></label><label class="sm-field"><text class="sm-field-label">上报对象</text><input v-model="form.report.recipient" class="sm-input" /></label></view><label class="sm-field"><text class="sm-field-label">上报方式</text><input v-model="form.report.method" class="sm-input" placeholder="实际使用的方式，如电话、现场报告" /></label><label class="sm-field"><text class="sm-field-label">上报后的整改要求</text><textarea v-model="form.report.requirements" class="sm-textarea" /></label></view>
    <view class="sm-expand sm-link" @click="showOnsite=!showOnsite">{{ showOnsite ? '收起' : '填写' }}当场整改事实 {{ showOnsite ? '−' : '+' }}</view>
    <view v-if="showOnsite"><label class="sm-field"><text class="sm-field-label">实际采取的措施</text><textarea v-model="form.onsite_rectification.measures" class="sm-textarea" /></label><view class="sm-grid"><label class="sm-field"><text class="sm-field-label">整改时间（北京时间）</text><input v-model="rectified" class="sm-input" placeholder="YYYY-MM-DD HH:mm" /></label><label class="sm-field"><text class="sm-field-label">复查时间（北京时间）</text><input v-model="rechecked" class="sm-input" placeholder="YYYY-MM-DD HH:mm" /></label></view><label class="sm-field"><text class="sm-field-label">复查情况</text><textarea v-model="form.onsite_rectification.recheck_note" class="sm-textarea" /></label><text class="sm-help">当场整改记录保留事实，正式复查销号仍通过原隐患整改流程办理。</text></view>
    <view class="sm-actions"><button class="sm-btn" :disabled="saving || evidenceUploading" @click="save">{{ saving ? '登记中…' : mode==='existing' ? '保存本次观察' : '立即登记隐患' }}</button><button class="sm-btn sm-btn--secondary" @click="$emit('cancel')">收起</button></view>
  </view>
</template>
<script setup>
import { computed, reactive, ref, watch } from 'vue'
import SafetyEvidenceEditor from './SafetyEvidenceEditor.vue'
import { registerSafetyIssue } from '@/services/safetyManagement'
import { listStationSafetyHazardsV1 } from '@/services/stationSafetyInspection'
import { beijingDate, formatDateTime, parseDateTime, requestId, showError } from './helpers'
const props = defineProps({ date:String, sourceType:{type:String,default:'supplement'}, sourceItemCode:String, sourceId:String, sourcePeriodStart:String, category:{type:Number,default:7}, title:{type:String,default:'登记或关联安全问题'}, hazards:{type:Array,default:()=>[]}, initialNote:{type:String,default:''}, evidence:{type:Array,default:()=>[]} })
const emit = defineEmits(['saved','cancel'])
const modes=[{value:'new',label:'新发现'},{value:'existing',label:'同一未关闭问题'},{value:'recurrence',label:'关闭后再次发生'}],levels=[{value:'general',label:'一般'},{value:'major',label:'重大'}]
const mode=ref('new'),saving=ref(false),evidenceUploading=ref(false),showReport=ref(false),showOnsite=ref(false),reported=ref(''),rectified=ref(''),rechecked=ref('')
const closedQuery=ref(''),closedAppliedQuery=ref(''),closedHazards=ref([]),closedLoading=ref(false),closedError=ref(''),closedPage=ref(0),closedTotal=ref(0),closedSearched=ref(false),selectedRecurrence=ref(null)
const closedHasMore=computed(()=>closedHazards.value.length<closedTotal.value)
async function searchClosed(more=false){if(closedLoading.value)return;closedLoading.value=true;closedError.value='';try{if(more && closedQuery.value.trim()!==closedAppliedQuery.value)more=false;const page=more?closedPage.value+1:1;const response=await listStationSafetyHazardsV1({status:'closed',keyword:closedQuery.value.trim(),page,pageSize:20});if(response?.code!==0)throw new Error(response?.msg || '无法查询已关闭隐患，请确认账号具有厂站隐患查看权限');const rows=response.data || [];closedHazards.value=more?[...closedHazards.value,...rows]:rows;closedPage.value=page;closedAppliedQuery.value=closedQuery.value.trim();closedTotal.value=Number(response.paging?.total || rows.length);closedSearched.value=true}catch(error){closedError.value=error.message}finally{closedLoading.value=false}}
function selectRecurrence(hazard){form.recurrence_of=hazard._id;selectedRecurrence.value=hazard}
const discovered=ref(props.date===beijingDate() ? formatDateTime(Date.now()) : '')
const form=reactive({client_submission_id:requestId('safety_issue'),issue_note:props.initialNote,hazard_level:'',responsible_name:'',planned_measure:'',planned_complete_date:'',temporary_controls:'',existing_hazard_id:'',recurrence_of:'',evidence:[...props.evidence],report:{recipient:'',method:'',requirements:''},onsite_rectification:{measures:'',recheck_note:''}})
const openHazards=computed(()=>props.hazards.filter(h=>!['closed','cancelled'].includes(h.current_status || h.status)).map(h=>({...h,optionLabel:`${h.hazard_no || h._id} · ${h.issue_note || h.item_label || ''}`})))
const selectedHazardLabel=computed(()=>openHazards.value.find(h=>h._id===form.existing_hazard_id)?.optionLabel)
watch(()=>form.existing_hazard_id,id=>{const source=openHazards.value.find(item=>item._id===id);if(source){form.hazard_level=source.hazard_level;form.responsible_name=source.responsible_name;form.planned_measure=source.planned_measure;form.planned_complete_date=source.planned_complete_date}})
async function save(){saving.value=true;try{if(evidenceUploading.value)throw new Error('请等待证据上传完成');if(!form.hazard_level)throw new Error('请明确选择隐患等级');if(mode.value==='recurrence' && !form.recurrence_of)throw new Error('请查询并选择已关闭的历史隐患');const payload={...form,date:props.date,source_type:props.sourceType,source_item_code:props.sourceItemCode,source_id:props.sourceId || '',source_period_start:props.sourcePeriodStart || '',management_category:props.category,discovered_at:parseDateTime(discovered.value),existing_hazard_id:mode.value==='existing'?form.existing_hazard_id:'',recurrence_of:mode.value==='recurrence'?form.recurrence_of:''};if(!Number.isFinite(payload.discovered_at)||!payload.discovered_at)throw new Error('请填写实际发现时间');if(showReport.value)payload.report={...form.report,reported_at:parseDateTime(reported.value)};else delete payload.report;if(showOnsite.value)payload.onsite_rectification={...form.onsite_rectification,rectified_at:parseDateTime(rectified.value),rechecked_at:parseDateTime(rechecked.value)};else delete payload.onsite_rectification;const result=await registerSafetyIssue(payload);emit('saved',result);uni.showToast({title:'问题已登记',icon:'success'})}catch(error){showError(error)}finally{saving.value=false}}
</script>
<style scoped>.sm-issue-editor { padding:24rpx; margin-top:20rpx; border:1rpx solid #f4d49d; border-radius:16rpx; background:#fffbf2; }.sm-closed-query{flex:1;min-width:220rpx}.sm-closed-result{padding:18rpx;margin:12rpx 0;border:1rpx solid #cbd5e1;border-radius:12rpx;background:white;cursor:pointer}.sm-closed-result--selected{border-color:#0284c7;background:#e0f2fe}</style>
